// Visual preview of the Beta Defend view with a MOCKED network (a synthetic AAOI-style put spread, generated by the REAL backend flow —
// see gen_defend_fixture.py). Nothing leaves the browser.
//   npm run dev  →  http://localhost:3000/scripts/beta-tests/preview/defend.html?case=after
//   ?case=after (default) | inside | healthy | naked | trap (ITM spread: anatomy · goals · ladder)  ·  &slow  ·  &fail=refine
import React from 'react';
import ReactDOM from 'react-dom/client';
import { MemoryRouter } from 'react-router-dom';
import '../../../src/index.css';
import BetaDefend from '../../../src/beta/BetaDefend';
import fixture from './defendFixture.json';

const params = new URLSearchParams(location.search);
const name = (params.get('case') || 'after') as keyof typeof fixture;
const fx = (fixture as any)[name] || (fixture as any).after;
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { 'Content-Type': 'application/json' } });
const real = window.fetch.bind(window);
window.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
  const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
  if (!url.includes('/api/')) return real(input, init);
  await new Promise(r => setTimeout(r, 300));
  if (url.includes('/repair-menu')) return json(fx.phase1 || fx.final);
  if (url.includes('/defend/refine')) {
    if (params.get('fail') === 'refine') return json({ detail: 'mock failure' }, 500);
    await new Promise(r => setTimeout(r, params.has('slow') ? 6000 : 1500));
    return json(fx.final);
  }
  return json({ detail: 'mock: not available in the preview' }, 404);
}) as typeof window.fetch;

function App() {
  return (
    <div className="container-app py-5">
      <div className="mb-3 rounded-lg border border-warning/30 bg-warning/10 px-3 py-1.5 text-xs text-warning">
        Preview with MOCK data — layout and wording check only (synthetic AAOI-style 80/70 put spread, real backend engine). Cases: <code>?case=after|inside|healthy|naked|trap</code> · <code>&amp;slow</code> · <code>&amp;fail=refine</code>
      </div>
      <BetaDefend tradeId={1} quoteSource="yfinance" ticker={name === 'naked' ? 'AMD' : 'AAOI'} />
    </div>
  );
}
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><MemoryRouter><App /></MemoryRouter></React.StrictMode>);
